import{_ as e,o as i,c as t,a3 as l}from"./chunks/framework.DACwFHq9.js";const h=JSON.parse('{"title":"贡献指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/contribution-guide.md","filePath":"guide/contribution-guide.md","lastUpdated":1784459228000}'),o={name:"guide/contribution-guide.md"};function s(n,a,c,r,d,p){return i(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="贡献指南" tabindex="-1">贡献指南 <a class="header-anchor" href="#贡献指南" aria-label="Permalink to &quot;贡献指南&quot;">​</a></h1><p>本指南记录 AIO Hub 的通用开发与提交约定。脚本、依赖和版本以仓库当前文件为准。</p><h2 id="_1-开始之前" tabindex="-1">1. 开始之前 <a class="header-anchor" href="#_1-开始之前" aria-label="Permalink to &quot;1. 开始之前&quot;">​</a></h2><ul><li>包管理器使用 Bun。安装依赖前先确认根目录或对应 workspace 的 <code>package.json</code>。</li><li>修改前阅读目标代码、相邻实现和相关架构文档，不要只根据目录名推断调用关系。</li><li>桌面端、移动端和 <code>packages/</code> workspace 可能有不同脚本；优先运行各自 <code>package.json</code> 中已有的命令。</li></ul><h2 id="_2-代码规范" tabindex="-1">2. 代码规范 <a class="header-anchor" href="#_2-代码规范" aria-label="Permalink to &quot;2. 代码规范&quot;">​</a></h2><h3 id="typescript-javascript" tabindex="-1">TypeScript / JavaScript <a class="header-anchor" href="#typescript-javascript" aria-label="Permalink to &quot;TypeScript / JavaScript&quot;">​</a></h3><ul><li>项目使用 Oxlint 做静态检查，使用 Prettier 统一格式。</li><li>避免无约束的 <code>any</code>；对跨模块数据、组件 Props 和公开方法定义明确类型。</li><li>变量与函数使用 <code>camelCase</code>，类型、类和组件使用 <code>PascalCase</code>，常量使用 <code>UPPER_SNAKE_CASE</code>。</li></ul><h3 id="vue" tabindex="-1">Vue <a class="header-anchor" href="#vue" aria-label="Permalink to &quot;Vue&quot;">​</a></h3><ul><li>使用 Vue 3 Composition API 与 <code>&lt;script setup lang=&quot;ts&quot;&gt;</code>。</li><li>优先复用项目组件、composable、主题 token 和反馈封装。</li><li>桌面与移动端的 UI 分层不同；新增工具前阅读<a href="./adding-new-tool">添加新工具指南</a>和<a href="./mobile-ui-development">移动端 UI 开发指南</a>。</li></ul><h2 id="_3-commit-message-规范" tabindex="-1">3. Commit Message 规范 <a class="header-anchor" href="#_3-commit-message-规范" aria-label="Permalink to &quot;3. Commit Message 规范&quot;">​</a></h2><p>提交信息遵循 <a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a>，description 使用当前协作语言。首行后必须包含背景和变更要点，不能只写单行标题。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;(&lt;scope&gt;): &lt;简述&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>背景：</span></span>
<span class="line"><span>&lt;为什么需要这次改动&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>变更要点：</span></span>
<span class="line"><span>- &lt;具体改动 1&gt;</span></span>
<span class="line"><span>- &lt;具体改动 2&gt;</span></span></code></pre></div><p>常用类型：</p><ul><li><code>feat</code>：真正面向用户的新功能。</li><li><code>fix</code>：缺陷修复。</li><li><code>docs</code>：纯文档修改。</li><li><code>refactor</code>：不改变外部行为的重构。</li><li><code>test</code>：测试补充或调整。</li><li><code>chore</code>：配置、依赖、版本和构建维护。</li></ul><p>提交信息不得包含 AI 内部状态标记。AI 智能体还必须遵守根目录 <code>AGENTS.md</code> 的授权边界，未经用户明确允许不得自行提交。</p><h2 id="_4-验证" tabindex="-1">4. 验证 <a class="header-anchor" href="#_4-验证" aria-label="Permalink to &quot;4. 验证&quot;">​</a></h2><ul><li>根据改动范围运行 lint、类型检查、单元测试和后端检查。</li><li>前端改动除类型检查外还要运行对应 Vite 构建。</li><li>Tauri 真实运行态和系统级交互按<a href="./tool-testing-guide">工具测试指南</a>选择验证层级，不能用普通浏览器结果替代。</li><li>提交前检查 diff，确认没有无关格式化、生成物、密钥或本地调试数据。</li></ul><h2 id="_5-git-工作流" tabindex="-1">5. Git 工作流 <a class="header-anchor" href="#_5-git-工作流" aria-label="Permalink to &quot;5. Git 工作流&quot;">​</a></h2><p>仓库采用常规分支与 Pull Request 工作流。创建分支、推送、提交或发起 PR 前，先确认任务授权和目标分支；不要假定所有改动都需要立即提交。</p>`,19)])])}const m=e(o,[["render",s]]);export{h as __pageData,m as default};
